"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Slot } from "radix-ui"

import { useInk, useMergedRef } from "@/lib/ink/react"
import { buttonRecipe } from "@/lib/ink/recipes/button-ink"
import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "relative isolate inline-flex shrink-0 items-center justify-center gap-2 font-medium whitespace-nowrap transition-[translate] duration-(--sd-dur-press) ease-out active:translate-y-(--sd-press-sink) disabled:pointer-events-none disabled:opacity-60 aria-disabled:pointer-events-none [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "text-primary-foreground",
        destructive: "text-primary-foreground",
        outline: "text-foreground",
        secondary: "text-secondary-foreground",
        ghost: "text-foreground",
        link: "text-[var(--sd-link)] underline-offset-4 hover:text-[var(--sd-link-hover)] hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 text-sm",
        sm: "h-8 px-3 text-sm",
        lg: "h-10 px-6 text-base",
        icon: "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
)

function Button({
  className,
  variant,
  size,
  asChild = false,
  disabled,
  seed,
  children,
  ref,
  onClick,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    seed?: string | number
  }) {
  const v = variant ?? "default"
  const s = size ?? "default"
  const pill = !!className && className.split(/\s+/).includes("rounded-full")
  const forced = "data-focus-visible" in props || "data-pressed" in props
  const { hostRef, hostProps, node } = useInk({
    recipe: buttonRecipe,
    params: { variant: v, size: s, disabled: !!disabled, shape: pill ? "pill" : "default" },
    kind: "button",
    seed,
    layers: forced ? "all" : undefined,
  })
  const mergedRef = useMergedRef<HTMLElement>(hostRef, ref as React.Ref<HTMLElement> | undefined)
  const shared = {
    "data-variant": v,
    "data-size": s,
    "data-shape": pill ? "pill" : undefined,
    "data-ink-sink": "self",
    className: cn(buttonVariants({ variant: v, size: s, className })),
    ref: mergedRef,
    ...hostProps,
    ...props,
  }

  if (asChild) {
    const inert = disabled
      ? {
          "aria-disabled": true as const,
          "data-disabled": "",
          tabIndex: -1,
          onClick: (e: React.MouseEvent<HTMLElement>) => e.preventDefault(),
        }
      : { onClick: onClick as React.MouseEventHandler<HTMLElement> | undefined }
    return (
      <Slot.Root data-slot="button" {...shared} {...inert}>
        <Slot.Slottable>{children}</Slot.Slottable>
        {node}
      </Slot.Root>
    )
  }

  return (
    <button data-slot="button" {...shared} disabled={disabled} onClick={onClick}>
      {node}
      {children}
    </button>
  )
}

export { Button, buttonVariants }

import { bandFill, wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { box, focusRing } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import { defineRecipe } from '@/lib/ink/recipes'

export const buttonVariantList = ['default', 'destructive', 'outline', 'secondary', 'ghost', 'link'] as const
export const buttonSizeList = ['default', 'sm', 'lg', 'icon'] as const
export type ButtonVariant = (typeof buttonVariantList)[number]
export type ButtonSize = (typeof buttonSizeList)[number]

export interface ButtonParams {
  variant: ButtonVariant
  size: ButtonSize
  disabled?: boolean
  shape?: 'default' | 'pill'
}

const fillFor = (variant: ButtonVariant): 'rose' | 'star' | 'sand-shade' | 'horizon' | 'danger' | null => {
  switch (variant) {
    case 'default':
      return 'rose'
    case 'secondary':
      return 'star'
    case 'destructive':
      return 'danger'
    case 'outline':
    case 'ghost':
    case 'link':
      return null
  }
}

export const buttonRecipe = defineRecipe<ButtonParams>({
  id: 'button',
  kind: 'button',
  layers: ['rest', 'hover', 'pressed', 'focus', 'disabled'],
  lazy: ['focus', 'pressed'],
  pad: 10,
  draw(ink, { w, h }, { variant, disabled, shape }, ctx) {
    const pill = shape === 'pill' && variant !== 'link'
    const r = pill ? Math.min(h, w) / 2 - 0.5 : clamp(h * 0.14, 3, 6)
    const inset = 0.6
    const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)
    const outlinePen = variant === 'destructive' ? 'rose.fine' : 'ink.fine'

    if (disabled) {
      if (ctx.lazyOnly) return
      ink.layer('disabled', () => {
        wash(ink, body, 'sand-shade', { alpha: 0.55, material: 'wash' })
        box(ink, 0.5, 0.5, w - 1, h - 1, { pen: 'pencil.fine', corner: r, opts: { alpha: 0.5 } })
      })
      return
    }

    ctx.lazy('focus', (fink) => focusRing(fink, 0, 0, w, h, { r }))
    ctx.lazy('pressed', (pink) => {
      const fill = fillFor(variant)
      if (fill) wash(pink, body, fill, { alpha: 0.28, material: 'wash' })
    })
    if (ctx.lazyOnly) return

    ink.layer('rest', () => {
      const fill = fillFor(variant)
      if (fill) {
        ink.part('fill', () => bandFill(ink, body, fill, { passes: ctx.calm ? 1 : 2, alpha: fill === 'danger' ? 0.92 : 0.78 }))
      }
      if (variant !== 'link') {
        box(ink, 0.5, 0.5, w - 1, h - 1, { pen: outlinePen, corner: r, loose: 0.85 })
      }
    })

    ink.layer('hover', () => {
      if (variant === 'ghost' || variant === 'link') {
        wash(ink, body, 'rose-wash', { alpha: 0.35 })
        return
      }
      box(ink, 1, 1, w - 2, h - 2, { pen: outlinePen, corner: r, loose: 0.7, opts: { alpha: 0.75, simple: true } })
    })
  },
})
